/**
 * Shared conversion utility for all unit categories
 * Extracted to follow DRY principle
 */

/**
 * Significant digits kept when no precision is given. Factors such as
 * 0.016666666666667 (1/60) are stored with 14 digits, so at 14 digits their
 * error shows up in a single conversion (24 K/min -> 0.40000000000001 K/s);
 * 12 hides it there. Chained conversions (unitConversion cycling through a
 * field) can still end one 12-digit step off, e.g. 1 d -> 0.999999999999 d.
 */
const DEFAULT_SIGNIFICANT_DIGITS = 12;

// Only a plain object is the { significant } form; arrays and boxed
// primitives (new Number(3)) go to toFixed, which coerced them before 3.0.
const isOptions = (p) =>
  Object.prototype.toString.call(p) === '[object Object]';

/**
 * Round a conversion result (see README "Rounding"):
 * - `precision` omitted: DEFAULT_SIGNIFICANT_DIGITS significant digits
 * - `{ significant: n }`: n significant digits ('3' acts as 3), clamped to
 *   1..100; a non-numeric n falls back to the default
 * - anything else: toFixed(precision), exactly as before 3.0 (decimal
 *   places; '3' acts as 3, null as 0)
 */
export function roundResult(value, precision) {
  if (precision !== undefined && !isOptions(precision)) {
    return Number(value.toFixed(precision));
  }
  const n = parseFloat(precision?.significant);
  const significant = Number.isFinite(n) ? n : DEFAULT_SIGNIFICANT_DIGITS;
  return Number(value.toPrecision(Math.min(Math.max(significant, 1), 100)));
}

/**
 * Generic conversion function that works for any unit category
 */
export function convertUnit(units, from, to, value, precision) {
  const fromUnit = units.fields.find((field) =>
    field.units.some((unit) => unit.key === from)
  );

  if (!fromUnit) return value;

  const toUnitField = units.fields.find((field) =>
    field.units.some((unit) => unit.key === to)
  );

  if (!toUnitField || fromUnit.field !== toUnitField.field) return value;

  const fromUnitData = fromUnit.units.find((unit) => unit.key === from);
  const toUnitData = toUnitField.units.find((unit) => unit.key === to);

  return roundResult(
    parseFloat(value) * (toUnitData.nm / fromUnitData.nm),
    precision
  );
}
